@@ -0,0 +1,39 @@
+{
+  "$schema": "https://json-schema.org/draft/2020-12/schema",
+  "$id": "https://grammark.dev/spec/cst-schema.json",
+  "title": "grammark-cst",
+  "description": "The generic concrete syntax tree a Grammark recognizer builds with no semantic actions: a branch per reduced production (tagged with its grammark-ir rules[] index) and a token leaf per consumed terminal, children in source order. This is the action-free, portable artifact every backend can emit and any host can walk. cstVersion 0 is draft/unstable and carries no compatibility promise.",
+  "type": "object",
+  "required": ["cstVersion", "root"],
+  "additionalProperties": false,
+  "properties": {
+    "cstVersion": { "type": "integer", "minimum": 0 },
+    "root": { "$ref": "#/$defs/node" }
+  },
+  "$defs": {
+    "node": {
+      "description": "A CST node is either an interior branch or a terminal leaf.",
+      "oneOf": [{ "$ref": "#/$defs/branch" }, { "$ref": "#/$defs/token" }]
+    },
+    "branch": {
+      "description": "A reduced production. `rule` is the index into grammark-ir grammar.rules; `children` are the right-hand-side nodes in source order (possibly empty only for an epsilon production, which the epsilon-free Core never emits).",
+      "type": "object",
+      "required": ["rule", "children"],
+      "additionalProperties": false,
+      "properties": {
+        "rule": { "type": "integer", "minimum": 0 },
+        "children": { "type": "array", "items": { "$ref": "#/$defs/node" } }
+      }
+    },
+    "token": {
+      "description": "A consumed terminal leaf. `token` is the terminal name (a literal spelling or an ALL-CAPS lexer class); `text` is the matched source slice.",
+      "type": "object",
+      "required": ["token", "text"],
+      "additionalProperties": false,
+      "properties": {
+        "token": { "type": "string" },
+        "text": { "type": "string" }
+      }
+    }
+  }
+}

